import type { Metadata } from "next";

const DEFAULT_SITE_ORIGIN = "https://bustrack-be165.web.app";

/**
 * Landscape 1200x630 card generated by `scripts/generate-social-card.mjs`.
 * Crawlers crop or reject portrait images for `summary_large_image`.
 */
export const SOCIAL_CARD_IMAGE = {
  url: "/images/social-card.jpg",
  width: 1200,
  height: 630,
  type: "image/jpeg",
  alt: "Eki: track your campus bus. Live bus locations for University routes",
} as const;

/**
 * Open Graph and Twitter metadata for one public page. Next.js merges
 * metadata shallowly, so a page that sets `openGraph` replaces the layout's
 * whole object; every public page therefore builds the full set here, with
 * its own URL, instead of inheriting the homepage's `og:url`.
 */
export function publicPageSocialMetadata(page: { path: `/${string}`; title: string; description: string }):
  Pick<Metadata, "openGraph" | "twitter"> {
  return {
    openGraph: {
      type: "website",
      url: page.path,
      title: page.title,
      description: page.description,
      siteName: "Eki Transit",
      images: [{ ...SOCIAL_CARD_IMAGE }],
    },
    twitter: {
      card: "summary_large_image",
      title: page.title,
      description: page.description,
      images: [{ url: SOCIAL_CARD_IMAGE.url, alt: SOCIAL_CARD_IMAGE.alt, width: SOCIAL_CARD_IMAGE.width, height: SOCIAL_CARD_IMAGE.height }],
    },
  };
}

/** One build-time origin for canonical, social metadata, robots and sitemap. */
export function resolveSiteOrigin(value: string | undefined, production = process.env.NODE_ENV === "production"): string {
  const raw = value?.trim() || DEFAULT_SITE_ORIGIN;
  let url: URL;
  try { url = new URL(raw); } catch { throw new Error("NEXT_PUBLIC_SITE_URL must be an absolute public origin."); }
  const local = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
  if ((url.protocol !== "https:" && !(url.protocol === "http:" && local && !production)) ||
      url.username || url.password || url.pathname !== "/" || url.search || url.hash) {
    throw new Error("NEXT_PUBLIC_SITE_URL must be an HTTPS origin without credentials, path, query or fragment.");
  }
  return url.origin;
}

export function siteOrigin(): string {
  return resolveSiteOrigin(process.env.NEXT_PUBLIC_SITE_URL);
}

export function siteIndexingEnabled(): boolean {
  return process.env.NEXT_PUBLIC_SITE_INDEXING !== "false";
}
